/* Policy editor concept: examples only; no execution-policy changes. */
const policyDraft={section:'Commits & branches',budgetMode:'Bounded',review:false};
const policySections={
  'Commits & branches':{title:'Repository delivery conventions',rules:[['Commit format','Required','Conventional Commits · type(scope): summary'],['Branch naming','Required','sabre/{run_id}/{short_slug}'],['PR structure','Required','Problem · change · evidence · limitations'],['PR target','Required','Draft pull request · protected default branch']]},
  'UI & design':{title:'Product and design preferences',rules:[['Component reuse','Required','Use existing project components and tokens'],['Visual direction','Preference','Dark operator console · restrained transparency'],['Interaction style','Preference','Progressive disclosure · keyboard-accessible inspection'],['Visual acceptance','Required','Review desktop and mobile evidence for UI changes']]},
  'Architecture & infra':{title:'Engineering and infrastructure policy',rules:[['Stack','Preference','Preserve the project stack and framework conventions'],['Module boundaries','Required','Keep execution, persistence and external adapters separate'],['Deployment','Preference','Local Docker Compose · pinned runtime images'],['Infrastructure changes','Required','Review material permission and infrastructure changes']]},
  'Security':{title:'Security and data boundaries',rules:[['Credentials','Required','Write-only, destination-bound credentials'],['Execution access','Required','Agent ∩ project ∩ run permissions'],['Blocking findings','Required','Unresolved mandatory findings block delivery'],['Telemetry content','Required','No secrets, prompts or source payloads in exported traces']]}
};
function policyEditor(){if(policyDraft.section==='Budgets')return budgetEditor();const p=policySections[policyDraft.section];return `<div class="panel"><div class="section-head"><div><div class="eyebrow">PROJECT OVERRIDE / DRAFT</div><h2>${p.title}</h2></div>${tag('v4 · published','green')}</div><p>Required rules are enforced by a registered validator. Preferences guide the agent and remain reviewable.</p><div class="stack">${p.rules.map(([name,kind,value])=>`<div class="policy-rule"><div><strong>${name}</strong><small>Source: ${name==='Visual direction'?'project override':'factory default'}</small></div>${tag(kind,kind==='Required'?'amber':'blue')}<input aria-label="${name}" value="${escape(value)}"></div>`).join('')}</div><div class="actions" style="margin-top:22px"><button class="primary" data-policy-review>Review policy draft</button><span class="muted" style="font-size:11px">Applies to future runs after publication.</span></div><div id="policy-preview" style="margin-top:16px"></div></div>`;}
function budgetEditor(){return `<section class="panel"><div class="eyebrow">RUN BUDGET / EXAMPLE PROFILE</div><h2>Choose how far the run can go</h2><p>Budgets control cumulative work. A blocked run keeps its checkpoint and can be resumed after an authorized adjustment.</p><div class="subnav">${['Bounded','With reserve','No cumulative cap'].map(mode=>`<button data-budget-mode="${mode}" aria-pressed="${policyDraft.budgetMode===mode}">${mode}</button>`).join('')}</div>${policyDraft.budgetMode==='No cumulative cap'?`<div class="notice">No run-level cumulative caps in this example.<br>Provider quotas, factory spending policy, permissions and per-operation safeguards still apply. Unknown CLI usage stays unknown until reported.</div><ul class="checklist"><li>Total tokens ${tag('Uncapped')}</li><li>Model calls ${tag('Uncapped')}</li><li>Active run time ${tag('Uncapped')}</li><li>Repair count ${tag('Uncapped')}</li></ul>`:`<div class="form-grid"><label class="field">Token budget<input type="number" min="1" value="100000"></label><label class="field">Model call budget<input type="number" min="1" value="40"></label><label class="field">Active time · minutes<input type="number" min="1" value="60"></label><label class="field">Repair cycles<input type="number" min="0" value="2"></label>${policyDraft.budgetMode==='With reserve'?'<label class="field">Additional tokens · preauthorized<input type="number" min="0" value="50000"><small>One reserve tranche; no automatic replenishment.</small></label><label class="field">Additional repairs · preauthorized<input type="number" min="0" value="1"></label>':''}</div>`}<h3 style="margin-top:25px">When a limit is reached</h3><ol class="budget-recovery"><li>Checkpoint the run and block further dispatch.</li><li>Notify the operator with usage, the exhausted limit and the pending action.</li><li>${policyDraft.budgetMode==='With reserve'?'Use only the remaining preauthorized reserve and record its activation.':'Offer an explicit budget adjustment.'}</li><li>Resume the same run after reconciliation; keep all usage and attempts.</li></ol><div class="notice">A failed check still blocks delivery. Unlimited repair count does not authorize tools, weaken tests or excuse repeated no-progress work.</div><button data-policy-review class="primary">Review example budget</button><div id="policy-preview" style="margin-top:16px"></div></section>`;}
function policyConsole(){return `<div class="policy-layout"><aside class="list-panel"><div class="eyebrow" style="padding:12px">POLICY DOMAINS</div>${[...Object.keys(policySections),'Budgets'].map(name=>`<button class="agent-row" data-policy-section="${name}" aria-pressed="${policyDraft.section===name}">${name}</button>`).join('')}</aside><div>${policyEditor()}<p class="footer-note">Resolve factory and project policy before launch. Run overrides can narrow permissions; relaxing a mandatory rule needs a separate authorized change. Conflicting rules block readiness.</p></div></div>`;}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.policySection){policyDraft.section=button.dataset.policySection;render();}if(button.dataset.budgetMode){policyDraft.budgetMode=button.dataset.budgetMode;render();}if(button.hasAttribute('data-policy-review')){const preview=document.getElementById('policy-preview');const values=[...document.querySelectorAll('.policy-rule input,.form-grid input')].map(input=>({field:input.getAttribute('aria-label')||input.closest('label').firstChild.textContent.trim(),value:input.value}));preview.innerHTML=`<div class="notice">Example draft preview only. No policy or run budget was changed.</div>${json({domain:policyDraft.section,mode:policyDraft.budgetMode,values,effect:'Future runs after authorized publication; active run changes require a separate budget amendment.'})}`;}});
